import type { ComponentPropsWithoutRef, ElementType, ReactNode } from "react";

/** Standard Craft Matrix block fields used by Drive CMS wrappers. */
export interface CmsBlockData {
	id: string;
	uid: string;
	title: string;
	headline?: string | null;
	copy?: string | null;
	hero?: Array<{
		url: string;
		alt?: string | null;
		width?: number;
		height?: number;
	}>;
	button?: Array<{
		text?: string | null;
		linkText?: string | null;
		url?: string | null;
		linkUrl?: string | null;
		newWindow?: string | boolean | null;
	}>;
}

/**
 * CmsBlockData aligns with SharedBlockContent in @/lib/component-content:
 *   title, headline, copy → copy fields
 *   hero[0]               → image
 *   button[0]             → button
 */

export type EditableMode = "inline" | "panel" | "focus";

export interface CmsFieldMapping {
	cmsField: keyof CmsBlockData | "componentHandle";
	prop: string;
	label: string;
	editable?: EditableMode;
	/** e.g. "comma-list" to split headline into string[] */
	format?: "comma-list";
}

export interface CmsComponentMeta {
	enabled: boolean;
	usesBlockStyles?: boolean;
	fields: CmsFieldMapping[];
}

export interface EditableFieldProps {
	subfield: string;
	label: string;
	inline?: boolean;
	panelOnly?: boolean;
	className?: string;
	as?: ElementType;
	children: ReactNode;
}

export type EditableComponent = (
	props: EditableFieldProps,
) => ReactNode;

export interface CmsBlockContext {
	fieldHandle: string;
	blockId: string;
	blockUid: string;
	entryId?: string;
	Editable: EditableComponent;
}

export type CmsBlockProps<TProps extends Record<string, unknown> = Record<string, unknown>> =
	CmsBlockContext & {
		data: CmsBlockData;
	} & TProps;

export type CmsBlockComponent<TProps extends Record<string, unknown> = Record<string, unknown>> =
	(props: CmsBlockProps<TProps>) => ReactNode;

export function mapCommaList(value?: string | null): string[] {
	if (!value?.trim()) {
		return [];
	}

	return value
		.split(/[,;]+/)
		.map((part) => part.trim())
		.filter(Boolean);
}

export function getBlockButton(data: CmsBlockData) {
	return data.button?.[0];
}

export function getBlockImage(data: CmsBlockData) {
	return data.hero?.[0];
}

"use client";

import React from "react";

import { RandomLetterSwapForward } from "@/registry/open-source/random-letter-swap-hover";

import {
	CmsBlockComponent,
	getBlockButton,
	getBlockImage,
} from "./_types";

/** Auto-generated CMS block for random-letter-swap-hover. */
export const randomLetterSwapHoverCmsMeta = {
	enabled: true,
	usesBlockStyles: true,
	fields: [
		{ cmsField: "title", prop: "title", label: "Title", editable: "inline" },
		{ cmsField: "headline", prop: "headline", label: "Headline", editable: "inline" },
		{ cmsField: "copy", prop: "copy", label: "Body", editable: "panel" },
		{ cmsField: "hero", prop: "image", label: "Image", editable: "focus" },
		{ cmsField: "button", prop: "button", label: "Call to action", editable: "focus" },
	],
} as const;

export const RandomLetterSwapHoverCmsBlock: CmsBlockComponent = ({ data, Editable }) => {
	const image = getBlockImage(data);
	const button = getBlockButton(data);

	return (
		<div className="relative w-full min-h-[240px] overflow-hidden">
			<Editable subfield="title" label="Title" inline>
				<h2 className="text-2xl font-semibold tracking-tight">
					{data.title || "Random Letter Swap Hover"}
				</h2>
			</Editable>
			{data.headline ? (
				<Editable subfield="headline" label="Headline" inline>
					<p className="mt-2 text-base text-neutral-600 dark:text-neutral-300">
						{data.headline}
					</p>
				</Editable>
			) : null}
			{data.copy ? (
				<Editable subfield="copy" label="Body">
					<p className="mt-3 text-sm text-neutral-500 dark:text-neutral-400">
						{data.copy}
					</p>
				</Editable>
			) : null}
			<Editable subfield="hero" label="Image">
				{image ? (
					<img
						src={image.url}
						alt={image.alt || data.title || "Random Letter Swap Hover"}
						width={image.width}
						height={image.height}
						className="mt-4 max-h-64 w-full rounded-lg object-cover"
					/>
				) : null}
			</Editable>
			{button ? (
				<Editable subfield="button" label="Call to action">
					<a
						href={button.url || button.linkUrl || "#"}
						target={button.newWindow ? "_blank" : undefined}
						rel={button.newWindow ? "noopener noreferrer" : undefined}
						className="mt-4 inline-flex rounded-md bg-neutral-900 px-4 py-2 text-sm text-white dark:bg-white dark:text-neutral-900"
					>
						{button.text || button.linkText || "Learn more"}
					</a>
				</Editable>
			) : null}
			<div className="mt-6 w-full">
				<RandomLetterSwapForward />
			</div>
		</div>
	);
};
